#[test]
fn captured_reply_decodes() {
    let reply = [0x11, 0x50, 0x49, 0x01, 0xf8, 0x24, 0x0a, 0xb4, 0x00, 0x07, 0x00, 0x06, 0x85, 0x00, 0x15, 0x0f, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0xe0, 0x01, 0x0a, 0x32, 0x50, 0x49, 0x01, 0xc0, 0x87, 0x04, 0x00, 0x00, 0x03, 0x00, 0x11, 0x86, 0x19, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00];
    assert_eq!(G435Protocol::parse_voltage(&reply), Ok(Some(3861)));
    let reading = BatteryReading::from_voltage(3861).unwrap();
    assert_eq!(reading.percentage(), 64);
    assert_eq!(reading.millivolts(), 3861);
    let mut windows_report = vec![0];
    windows_report.extend_from_slice(&reply);
    assert_eq!(G435Protocol::parse_voltage(&windows_report), Ok(Some(3861)));
    windows_report[13] = 0x81;
    assert_eq!(G435Protocol::parse_voltage(&windows_report), Ok(None));
}

#[test]
fn voltage_validation_and_bounds() {
    assert_eq!(BatteryReading::from_voltage(3400).unwrap().percentage(), 0);
    assert_eq!(BatteryReading::from_voltage(4200).unwrap().percentage(), 100);
    assert!(BatteryReading::from_voltage(3600).unwrap().is_low());
    assert_eq!(BatteryReading::from_voltage(1000), Err(BatteryError::InvalidVoltage));
    assert_eq!(G435Protocol::parse_voltage(&[0;7]), Ok(None));
}
